Figure C1.1. The baseline path with the design chosen, by country

import {pathGrid, control, checkboxes, COUNTRIES, COSTFORMS, countryStyle, OUTCOMES} from "./assets/oa.js"
escPaths = FileAttachment("_generated/data/ESC_Paths.csv").csv({typed: true})
PATHVARS = [["Pension design θ", "theta"], ["Tax rate", "tau"], ["Savings over GDP", "sr"], ["Workweek", "workweek"]]
COSTS = [["the U.S. one for all", "US"], ["each country's own", "own"]]
NAME = ({US: "U.S.", UK: "UK", FR: "France"})
// One country's baseline path at rho = 1 under the selected cost (linear or squared) and parameter (the U.S. one or its own).
countryPath = (country, cost, form) =&gt; escPaths.filter(d =&gt; (d.source === "main" || d.source === "host")
  && d.country === country && d.spec === "size" && d.rho === 1 && d.wedgeFrom === cost && d.cost === form)
series = (rows, variable, reading) =&gt; rows.filter(d =&gt; d.variable === variable)
  .map(d =&gt; ({year: d.year, value: d[reading]})).sort((a, b) =&gt; a.year - b.year)
viewof c1Countries = checkboxes(COUNTRIES, {key: "countries", label: "Countries"})
viewof c1Var = control("select", PATHVARS, {key: "variable", label: "Beside workers per retiree", value: "theta"})
viewof c1Form = control("radio", COSTFORMS, {key: "k", label: "Cost of redistribution", value: "linear"})
viewof c1Cost = control("radio", COSTS, {key: "cost", label: "Cost parameter", value: "US"})
{
  const lines = v =&gt; c1Countries.map(c =&gt; {
    const st = countryStyle(c);
    return {label: NAME[c], colour: st.colour, symbol: st.symbol,
            records: series(countryPath(c, c1Cost, c1Form), v, v === "nu" ? "pinned" : "chosen")};
  });
  const observed = c1Var === "theta" ? c1Countries.map(c =&gt; {
    const r = countryPath(c, c1Cost, c1Form).find(d =&gt; d.variable === "theta" && d.year === 2020);
    return r ? {year: 2020, value: r.pinned, colour: countryStyle(c).colour, text: `${NAME[c]}, observed design: ${r.pinned.toFixed(3)}`} : null;
  }).filter(d =&gt; d) : [];
  const items = c1Countries.map(c =&gt; ({label: NAME[c], colour: countryStyle(c).colour, shape: "line"}));
  if (observed.length) items.push({label: "observed design", colour: "#52514e", shape: "open"});
  return pathGrid([{title: "Workers per retiree ν", variable: "nu", lines: lines("nu"), rule: 2020, ruleLabel: "calibration"},
                   {title: OUTCOMES[c1Var].level, variable: c1Var, lines: lines(c1Var), rule: 2020,
                    ruleLabel: "calibration", observed}],
                  items, {width});
}





















































































\(\cdot\)
Note: Log preferences (\(\rho = 1\)), under the cost selected, linear in the tax rate or with the tax rate squared, each calibrated on its own. Each country keeps its own calibration and demography; the cost parameter is the U.S. one or the country’s own, as selected, where one re-elects its observed design. A design chosen at one date applies from the following one. Open markers are the observed designs.Data: the figure’s data (csv) · SourceReads:data/USMain_test.xlsxresults/esc/escCalibration.csvresults/esc/escCalibrationCRRA.csvresults/esc/escPath.csvresults/esc/escPathCRRA.csvresults/esc/escPathHost.csvresults/esc/escXiRobustness.csvresults/esc_tau1/escCalibration.csvresults/esc_tau1/escCalibrationCRRA.csvresults/esc_tau1/escPath.csvresults/esc_tau1/escPathCRRA.csvresults/esc_tau1/escPathHost.csvresults/esc_tau1/escXiRobustness.csvresults/paper/usCalibrationSummary.csvBuilt by siteData.escPaths (python/paper) at commit 07491fd. Rebuild: python python/paper/build.py --no-copy --only ESC_Paths.

The design chosen and the design pinned
With the design pinned at its observed value, each country’s path is that of section 6 with the cost in place. After 2020 the tax rate with the design chosen lies above the pinned path in every country, under either cost and either parameter, consistent with the hump of C2: at a given demography the tax rate peaks just above the design the electorate chooses, so a design pinned well away from that choice carries a lower one. At each country’s own parameter, the U.S. included, the chosen design rises above the observed one after 2020 as the population ages, and the tax rate lies above the pinned path by less under the linear cost than under the squared: in the U.S. by up to about four tenths of a percentage point against about one and a quarter, in the UK by up to a fifth of a point against three fifths, and in France by a few hundredths against a tenth. Under the U.S. parameter the UK’s chosen design lies above its observed one throughout, and France’s below it, until 2020 under the squared cost and throughout under the linear cost; the gap in the tax rate is largest in the UK.

\(\cdot\)
Figure C1.2. The baseline path with the design chosen and with it pinned

viewof c1bCountry = control("radio", COUNTRIES, {key: "country", label: "Country", value: "US"})
viewof c1bVar = control("select", PATHVARS, {key: "variable2", label: "Beside workers per retiree", value: "theta"})
viewof c1bForm = control("radio", COSTFORMS, {key: "k2", label: "Cost of redistribution", value: "linear"})
viewof c1bCost = control("radio", COSTS, {key: "cost2", label: "Cost parameter", value: "US"})
{
  const rows = countryPath(c1bCountry, c1bCost, c1bForm);
  const st = countryStyle(c1bCountry);
  const both = v =&gt; [
    {label: NAME[c1bCountry] + ", design chosen", colour: st.colour, symbol: st.symbol,
     records: series(rows, v, "chosen")},
    {label: NAME[c1bCountry] + ", design pinned", colour: st.colour, symbol: st.symbol, dashed: true,
     records: series(rows, v, "pinned")}];
  const items = [{label: "design chosen", colour: st.colour, shape: "line"},
                 {label: "design pinned at the observed value", colour: st.colour, shape: "line", dashed: true}];
  return pathGrid([{title: "Workers per retiree ν", variable: "nu", rule: 2020, ruleLabel: "calibration",
                    lines: [{label: NAME[c1bCountry], colour: st.colour, symbol: st.symbol, records: series(rows, "nu", "chosen")}]},
                   {title: OUTCOMES[c1bVar].level, variable: c1bVar, lines: both(c1bVar), rule: 2020, ruleLabel: "calibration"}],
                  items, {width});
}




































